<?php

namespace Testcontainers\Docker\Types;

use Testcontainers\Utility\Ensure;
use Testcontainers\Exceptions\InvalidFormatException;
use Testcontainers\Utility\Stringable;

/**
 * Represents the scope of a Docker event.
 * @api
 */
class EventScope implements Stringable
{
    use Ensure;

    /**
     * The scope of events generated by the local engine.
     *
     * @var string
     * @psalm-var mixed
     */
    public static $LOCAL = 'local';

    /**
     * The scope of events generated by the swarm cluster.
     *
     * @var string
     * @psalm-var mixed
     */
    public static $SWARM = 'swarm';

    /**
     * The scope of the event.
     *
     * @var string
     */
    private $scope;

    /**
     * @param string $scope
     * @psalm-param mixed $scope
     */
    public function __construct($scope)
    {
        self::ensureString($scope);

        if (!in_array($scope, self::values(), true)) {
            throw new InvalidFormatException($scope, self::values());
        }

        $this->scope = $scope;
    }

    public function __toString()
    {
        return $this->toString();
    }

    /**
     * Create a new instance of `EventScope` with the `LOCAL` scope.
     *
     * @return self
     */
    public static function LOCAL()
    {
        return new self(static::$LOCAL);
    }

    /**
     * Create a new instance of `EventScope` with the `SWARM` scope.
     *
     * @return self
     */
    public static function SWARM()
    {
        return new self(static::$SWARM);
    }

    /**
     * Create a new instance of `EventScope` from a string representation.
     *
     * @param string $scope the string representation of the scope
     * @psalm-param mixed $scope
     *
     * @throws InvalidFormatException if the provided scope is not valid
     *
     * @return self
     */
    public static function fromString($scope)
    {
        self::ensureString($scope);

        if (!in_array($scope, self::values(), true)) {
            throw new InvalidFormatException($scope, self::values());
        }

        return new self($scope);
    }

    /**
     * Get all valid values.
     *
     * @return string[]
     */
    public static function values()
    {
        return self::ensureStringList([
            static::$LOCAL,
            static::$SWARM,
        ]);
    }

    /**
     * Check if the scope is `LOCAL`.
     *
     * @return bool true if the scope is `LOCAL`, false otherwise
     */
    public function isLocal()
    {
        return $this->scope === static::$LOCAL;
    }

    /**
     * Check if the scope is `SWARM`.
     *
     * @return bool true if the scope is `SWARM`, false otherwise
     */
    public function isSwarm()
    {
        return $this->scope === static::$SWARM;
    }

    /**
     * Get the string representation of the scope.
     *
     * @return string the string representation of the scope
     */
    public function toString()
    {
        return $this->scope;
    }
}
